// All 10 EBGaramond TTFs — pre-encoded as base64 data URI string constants.
// No webpack rules, no .ttf imports, no network requests.
// ~7 MB of base64 strings; only loaded when the PDF generator is used.

const regular = 'data:font/ttf;base64,';

const italic = 'data:font/ttf;base64,';

const medium = 'data:font/ttf;base64,';

const mediumItalic = 'data:font/ttf;base64,';

const semiBold = 'data:font/ttf;base64,';

const semiBoldItalic = 'data:font/ttf;base64,';

const bold = 'data:font/ttf;base64,';

const boldItalic = 'data:font/ttf;base64,';

const extraBold = 'data:font/ttf;base64,';

const extraBoldItalic = 'data:font/ttf;base64,';

export const EBGARAMOND_FONTS = {
  family: 'EBGaramond',
  fonts: [
    { src: regular, fontStyle: 'normal' as const, fontWeight: 400 },
    { src: italic, fontStyle: 'italic' as const, fontWeight: 400 },
    { src: medium, fontStyle: 'normal' as const, fontWeight: 500 },
    { src: mediumItalic, fontStyle: 'italic' as const, fontWeight: 500 },
    { src: semiBold, fontStyle: 'normal' as const, fontWeight: 600 },
    { src: semiBoldItalic, fontStyle: 'italic' as const, fontWeight: 600 },
    { src: bold, fontStyle: 'normal' as const, fontWeight: 700 },
    { src: boldItalic, fontStyle: 'italic' as const, fontWeight: 700 },
    { src: extraBold, fontStyle: 'normal' as const, fontWeight: 800 },
    { src: extraBoldItalic, fontStyle: 'italic' as const, fontWeight: 800 },
  ],
};
